// Generated by AI (UnitTest MCP)
//! Deterministic symbol and call-graph extraction (heuristic, zero-token).
//!
//! Pattern-based extraction covering the common languages. It finds symbol
//! **definitions** and, within each callable definition's body, **call sites**
//! that reference another symbol defined in the same file — emitting in-file
//! `calls` edges. Structured behind [`extract`] so a Tree-sitter backend can
//! replace the heuristics later (for cross-file / scope-accurate resolution)
//! without touching callers.
//!
//! Split across submodules to stay under the repo module-length ratchet:
//! `types` (Symbol/Call/CallReference/Extraction/Def), `language`
//! (per-language definition patterns), `defs` (finding raw definitions with
//! cached compiled regexes), `rust_owner` (qualifying Rust methods by their
//! `impl` owner), `body` (definition body-span computation), `call_sites`
//! (heuristic call-site discovery), `extract` (the main analysis pass), and
//! `context` (the embedding-context extraction, independent of the rest).

mod body;
mod call_sites;
mod context;
mod defs;
mod extract;
mod language;
mod rust_owner;
mod types;

pub use context::symbol_context;
pub use extract::{extract, extract_symbols};
pub use types::{Call, CallReference, Extraction, Symbol};

#[cfg(test)]
mod tests {
    use std::sync::Arc;

    use super::context::MAX_CONTEXT_CHARS;
    use super::defs::compiled_pattern;
    use super::{extract, extract_symbols, symbol_context, Call, CallReference};

    #[test]
    fn compiled_pattern_caches_and_reuses_the_same_regex() {
        let a = compiled_pattern(r"^\s*fn\s+(\w+)").expect("valid pattern");
        let b = compiled_pattern(r"^\s*fn\s+(\w+)").expect("valid pattern");
        // Same pattern text -> the same cached instance, not a fresh compile.
        assert!(Arc::ptr_eq(&a, &b));
        // A malformed pattern is skipped, exactly as the old Regex::new match.
        assert!(compiled_pattern(r"(").is_none());
    }

    #[test]
    fn symbol_context_keeps_the_declaration_and_its_doc_comment() {
        // The regression: a symbol embedded as its name alone, so querying the
        // literal identifier `effective_weight` did not return it.
        let source = "\
/// The half-life decay applied at read time.
/// Never stored, always derived.
pub fn effective_weight(base: f64, age_hours: f64) -> f64 {
    base
}
";
        let context = symbol_context(source, 3);

        assert!(context.contains("The half-life decay applied at read time."));
        assert!(context.contains("Never stored, always derived."));
        assert!(context.contains("pub fn effective_weight"));
    }

    #[test]
    fn symbol_context_steps_over_attributes_to_reach_the_doc() {
        let source = "\
/// Reap decayed edges.
#[inline]
pub fn prune() {}
";
        let context = symbol_context(source, 3);

        assert!(context.contains("Reap decayed edges."));
        assert!(context.contains("pub fn prune"));
    }

    #[test]
    fn symbol_context_stops_at_unrelated_code() {
        // A blank line or a previous statement is not this symbol's doc.
        let source = "\
let unrelated = 1;

pub fn recall() {}
";
        let context = symbol_context(source, 3);

        assert_eq!(context, "pub fn recall() {}");
    }

    #[test]
    fn symbol_context_handles_hash_comments_but_not_rust_attributes() {
        let python = "# Build the working set.\ndef working_set():\n    pass\n";
        assert!(symbol_context(python, 2).contains("Build the working set."));

        let rust = "#[derive(Debug)]\npub struct Node;\n";
        assert_eq!(symbol_context(rust, 2), "pub struct Node;");
    }

    #[test]
    fn symbol_context_is_bounded_and_survives_a_line_past_the_end() {
        let long = format!("/// {}\npub fn wide() {{}}\n", "x".repeat(2_000));
        assert!(symbol_context(&long, 2).chars().count() <= MAX_CONTEXT_CHARS);

        assert_eq!(symbol_context("pub fn only() {}", 99), "");
        assert_eq!(symbol_context("", 0), "");
    }

    #[test]
    fn extracts_rust_symbols() {
        let src = "pub fn validate_session() {}\nstruct Session {}\n";
        let syms = extract_symbols("src/auth.rs", src);
        assert!(syms
            .iter()
            .any(|s| s.name == "validate_session" && s.kind == "fn"));
        assert!(syms
            .iter()
            .any(|s| s.name == "Session" && s.kind == "struct"));
    }

    #[test]
    fn extracts_typescript_symbols() {
        let src = "export function validateSession() {}\nclass Auth {}\nexport const run = async () => {}\n";
        let syms = extract_symbols("src/auth.ts", src);
        assert!(syms.iter().any(|s| s.name == "validateSession"));
        assert!(syms.iter().any(|s| s.name == "Auth" && s.kind == "class"));
        assert!(syms.iter().any(|s| s.name == "run" && s.kind == "arrow"));
    }

    #[test]
    fn line_numbers_are_one_based() {
        let src = "\n\ndef helper():\n    pass\n";
        let syms = extract_symbols("x.py", src);
        assert_eq!(syms[0].line, 3);
    }

    #[test]
    fn unknown_extension_yields_nothing() {
        assert!(extract_symbols("data.bin", "garbage").is_empty());
    }

    #[test]
    fn extracts_rust_call_edges() {
        let src = "fn a() {\n    b();\n    helper();\n}\nfn b() {}\nfn helper() {}\n";
        let calls = extract("src/x.rs", src).calls;
        assert!(calls.contains(&Call {
            caller: "a".into(),
            callee: "b".into()
        }));
        assert!(calls.contains(&Call {
            caller: "a".into(),
            callee: "helper".into()
        }));
    }

    #[test]
    fn extracts_python_call_edges() {
        let src = "def a():\n    b()\n\ndef b():\n    pass\n";
        let calls = extract("m.py", src).calls;
        assert_eq!(
            calls,
            vec![Call {
                caller: "a".into(),
                callee: "b".into()
            }]
        );
    }

    #[test]
    fn ignores_self_recursion_and_unknown_callees() {
        let src = "fn a() {\n    a();\n    unknown_fn();\n}\n";
        let calls = extract("src/x.rs", src).calls;
        assert!(calls.is_empty()); // self-loop skipped; unknown_fn not defined here
    }

    #[test]
    fn separates_unresolved_references_from_in_file_calls() {
        let src = "fn caller() {\n    local();\n    imported();\n}\nfn local() {}\n";
        let extraction = extract("src/x.rs", src);

        assert_eq!(
            extraction.calls,
            vec![Call {
                caller: "caller".into(),
                callee: "local".into(),
            }]
        );
        assert_eq!(
            extraction.call_references,
            vec![CallReference {
                caller: "caller".into(),
                callee: "imported".into(),
            }]
        );
    }

    #[test]
    fn javascript_references_ignore_comments_strings_members_and_shadowing() {
        let source = r#"
export function caller(dependency) {
    // dependency();
    const text = "dependency()";
    other.dependency();
    dependency();
}
export function localShadow() {
    const dependency = () => {};
    dependency();
}
"#;
        let extraction = extract("src/consumer.ts", source);

        assert!(!extraction
            .call_references
            .iter()
            .any(|reference| reference.callee == "dependency"));
    }

    #[test]
    fn javascript_body_span_ignores_braces_in_strings_comments_and_templates() {
        let source = r#"
export function consumer() {
    const close = "}";
    const open = `{`;
    // }
    dependency();
}
"#;
        let extraction = extract("src/consumer.ts", source);

        assert!(extraction.call_references.contains(&CallReference {
            caller: "consumer".to_string(),
            callee: "dependency".to_string(),
        }));
    }

    #[test]
    fn nested_shadow_does_not_hide_outer_imported_call() {
        let source = r#"
export function consumer() {
    dependency();
    if (condition) {
        const dependency = local;
        dependency();
    }
}
"#;
        let extraction = extract("src/consumer.ts", source);

        assert_eq!(
            extraction
                .call_references
                .iter()
                .filter(|reference| reference.callee == "dependency")
                .count(),
            1
        );
    }

    #[test]
    fn javascript_local_function_call_is_not_filtered_as_shadowed() {
        let source = "export function caller() { callee(); }\nfunction callee() {}\n";
        let extraction = extract("src/consumer.ts", source);

        assert!(extraction.calls.contains(&Call {
            caller: "caller".to_string(),
            callee: "callee".to_string(),
        }));
    }

    #[test]
    fn parameter_shadow_prevents_false_same_file_call() {
        let source = "function dependency() {}\nfunction caller(dependency) { dependency(); }\n";
        let extraction = extract("src/consumer.ts", source);

        assert!(!extraction
            .calls
            .iter()
            .any(|call| { call.caller == "caller" && call.callee == "dependency" }));
    }

    #[test]
    fn property_and_type_names_are_not_parameter_bindings() {
        let source = r#"
export function consumer({ dependency: local }, value: typeof Factory) {
    dependency();
}
"#;
        let extraction = extract("src/consumer.ts", source);

        assert!(extraction.call_references.contains(&CallReference {
            caller: "consumer".to_string(),
            callee: "dependency".to_string(),
        }));
    }

    #[test]
    fn destructured_parameters_and_typed_return_keep_real_body_span() {
        let source = r#"
export function consumer({ flag }): void {
    dependency();
}
"#;
        let extraction = extract("src/consumer.ts", source);

        assert!(extraction.call_references.contains(&CallReference {
            caller: "consumer".to_string(),
            callee: "dependency".to_string(),
        }));
    }

    #[test]
    fn default_arrow_parameter_and_function_type_return_keep_outer_body() {
        let source = r#"
export const arrowConsumer = (callback = () => {}) => {
    dependency();
};
export function typedConsumer(): () => { value: string } {
    dependency();
}
"#;
        let extraction = extract("src/consumer.ts", source);

        assert!(extraction.call_references.contains(&CallReference {
            caller: "arrowConsumer".to_string(),
            callee: "dependency".to_string(),
        }));
        assert!(extraction.call_references.contains(&CallReference {
            caller: "typedConsumer".to_string(),
            callee: "dependency".to_string(),
        }));
    }

    #[test]
    fn comments_and_templates_do_not_create_symbol_definitions() {
        let source = r#"
/*
function ghostFromComment() {}
*/
const text = `
function ghostFromTemplate() {}
`;
export function real() {}
"#;
        let extraction = extract("src/consumer.ts", source);

        assert_eq!(
            extraction
                .symbols
                .iter()
                .map(|symbol| symbol.name.as_str())
                .collect::<Vec<_>>(),
            vec!["real"]
        );
    }

    #[test]
    fn attributes_call_to_innermost_definition() {
        // A call inside `b` must be attributed to b, not the earlier `a`.
        let src = "fn a() {}\nfn b() {\n    a();\n}\n";
        let calls = extract("src/x.rs", src).calls;
        assert_eq!(
            calls,
            vec![Call {
                caller: "b".into(),
                callee: "a".into()
            }]
        );
    }
}
